# Public API (util.*)
  @api util.print(...)  @ 7-13
  @api util.print_r(root)  @ 19-38
  @api util.assign(t1,t2)  @ 46-57
      @contract  values equal to util.REMOVE clear the key from t1 instead of being assigned  @ 45
  @api util.add(tbl, val)  @ 59-62
  @api util.atomic(label, fn)  @ 68-77
      -- Wrap fn so each call is one REAPER undo entry. label is the undo
      -- description; the wrapper forwards args, propagates errors after
      -- closing the block, and is a no-op when reaper.Undo_BeginBlock is
      -- absent (test harness).
  @api util.picker(keys)  @ 82-97
      -- pick re-parses its key string on every call: nothing at a site that runs a few times, and
      -- 9.6ms of pure gmatch at one that runs per note of a dense channel. Hoist a picker there.
      @contract  parses `keys` once, returns a pick over it; the closure owns the list, no module state  @ 79
  @api util.pick(src, keys, adds)  @ 99-108
  @api util.bucket(buckets, key, val)  @ 110-115
  @api util.key(...)  @ 121-135
      -- Opaque compound key: join identity fields with NUL, which can't appear
      -- in a guid, track-key, or stringified scalar. Never split back apart.
      -- Small arities unroll to a single concat (per-event on the load/rebuild key
      -- paths); tostring kept per arg so output is identical for any arg type.
  @api util.keyFrom(parts)  @ 139-143
      -- The same key from a list a caller has built its parts up in: unpacking a long one
      -- onto the stack to pass it costs more than the join it is passed for.
  @api util.keys(t)  @ 145-149
  @api util.compact(t, n)  @ 152-156
      -- Sparse → dense; n is the pre-sparse length.
  @api util.seek(items, mode, key, filter, keyFn)  @ 159-180
      @contract  assumes items sorted by keyFn (defaults to .ppq); 'before' modes scan to first miss then stop  @ 158
  @api util.insertSorted(list, item, less)  @ 184-192
      -- Splice item into an already-sorted list at its lower bound (before any element not less than it),
      -- by the same less-than a table.sort(list, less) would use. O(log n) search plus the shift.
  @api util.clone(src, exclude, deep)  @ 195-204
      @contract  exclude applies only to the outermost table; deep recursion drops the exclude set  @ 194
  @api util.deepClone(src)  @ 206
  @api util.deepEq(a, b)  @ 208-214
